select count(*)
from oa_attendance_correction_request
where user_id = #{userId} and schedule_id = #{scheduleId}
  and target_punch_type = #{targetPunchType}
  and correction_request_id != coalesce(#{excludeId}, -1)
  and status in ('DRAFT', 'SUBMITTING', 'PENDING', 'APPROVED', 'RETURNED')

select count(*)
from oa_attendance_correction_request
where user_id = #{userId} and schedule_id = #{scheduleId}
  and target_punch_slot_key = #{targetPunchSlotKey}
  and correction_request_id != coalesce(#{excludeId}, -1)
  and status in ('DRAFT', 'SUBMITTING', 'PENDING', 'APPROVED', 'RETURNED')

select count(*)
from oa_attendance_correction_request
where user_id = #{userId}
  and original_punch_event_id = #{originalPunchEventId}
  and correction_request_id != coalesce(#{excludeId}, -1)
  and status in ('DRAFT', 'SUBMITTING', 'PENDING', 'APPROVED', 'RETURNED')

mapper.update:
update oa_attendance_correction_request
set status = 'PENDING', approval_instance_id = #{instanceId},
    row_version = row_version + 1, update_by = #{updateBy},
    update_time = now()
where correction_request_id = #{correctionRequestId}
  and status = 'SUBMITTING'
  and business_round = #{businessRound}
  and row_version = #{expectedVersion}
  and approval_instance_id is null

